package com.campusmart.service;
import com.campusmart.entity.User;import com.campusmart.repository.UserRepository;import com.campusmart.dto.AuthDtos;import com.campusmart.security.JwtService;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.security.SecureRandom;
@Service public class UserService{private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;private final SecureRandom random=new SecureRandom();public UserService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}public Object register(AuthDtos.Register r){if(!r.password().equals(r.confirmPassword()))throw new IllegalArgumentException("Passwords do not match");if(users.findByEmail(r.email().toLowerCase()).isPresent())throw new IllegalArgumentException("Email already registered");if(!r.email().toLowerCase().matches("^[^@]+@[^@]+\\.[^@]+$"))throw new IllegalArgumentException("Enter a valid college email");User u=new User();u.setFullName(r.fullName().trim());u.setEmail(r.email().toLowerCase().trim());u.setPassword(encoder.encode(r.password()));u.setCollegeName(r.collegeName().trim());u.setStudentId(r.studentId().trim());u.setRole(User.Role.STUDENT);u.setVerified(false);u.setVerificationCode(String.format("%06d",random.nextInt(1000000)));users.save(u);return java.util.Map.of("message","Registration created. Verify your account using the development code.","verificationCode",u.getVerificationCode());}public AuthDtos.AuthResponse login(AuthDtos.Login r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("Invalid email or password");if(!u.isVerified())throw new IllegalArgumentException("Please verify your college email first");return new AuthDtos.AuthResponse(jwt.create(u.getId(),u.getEmail(),u.getRole().name()),u.getId(),u.getFullName(),u.getEmail(),u.getRole().name());}public void verify(AuthDtos.Verify r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Account not found"));if(!u.getVerificationCode().equals(r.code()))throw new IllegalArgumentException("Invalid verification code");u.setVerified(true);u.setVerificationCode(null);users.save(u);}public User get(Long id){return users.findById(id).orElseThrow(()->new IllegalArgumentException("User not found"));}}
